
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ncap_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ncap", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.308488619583578e+00, -4.226935793243996e+00, -4.112783504293567e+00, -3.954912363219992e+00, -3.740336837529715e+00, -3.455900526995562e+00, -3.092204611083718e+00, -2.650549799189695e+00, -2.151468737137544e+00, -1.634026218408753e+00, -1.116699891681040e+00, -7.117848103512883e-01, -6.024947003650263e-01, -5.027103927846348e-01, -3.740808254684192e-01, -2.541082272451404e-01, -1.735415306339149e-01, -1.617396079486099e-01, -2.561320099268008e-01, -5.120708389871611e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


